# This code generated by ai use for only understanding perpose
EMPTY = " "
HUMAN = "X"
AI = "O"


def check_winner(board):
    """Returns 'O' (AI win), 'X' (Human win), 'DRAW', or None if game continues."""
    lines = (
        board[0],
        board[1],
        board[2],  # Rows
        [board[0][0], board[1][0], board[2][0]],  # Col 0
        [board[0][1], board[1][1], board[2][1]],  # Col 1
        [board[0][2], board[1][2], board[2][2]],  # Col 2
        [board[0][0], board[1][1], board[2][2]],  # Main diagonal
        [board[0][2], board[1][1], board[2][0]],  # Anti diagonal
    )

    for line in lines:
        if line[0] != EMPTY and line[0] == line[1] == line[2]:
            return line[0]

    # If no empty spots remain and nobody won, it's a draw
    if not any(EMPTY in row for row in board):
        return "DRAW"

    return None


def minimax(board, depth, is_maximizing):
    """
    Recursively scores all possible game paths.
    - AI ('O') tries to maximize score (+10 - depth).
    - Human ('X') tries to minimize score (-10 + depth).
    """
    winner = check_winner(board)
    if winner == AI:
        return 10 - depth  # Prefer faster wins
    if winner == HUMAN:
        return -10 + depth  # Prefer slower losses
    if winner == "DRAW":
        return 0

    if is_maximizing:
        best_score = -999
        for r in range(3):
            for c in range(3):
                if board[r][c] == EMPTY:
                    board[r][c] = AI  # 1. Simulate move
                    score = minimax(
                        board, depth + 1, False
                    )  # 2. Recurse down tree
                    board[r][c] = EMPTY  # 3. Undo move (backtrack)
                    best_score = max(best_score, score)
        return best_score
    else:
        best_score = 999
        for r in range(3):
            for c in range(3):
                if board[r][c] == EMPTY:
                    board[r][c] = HUMAN  # 1. Simulate move
                    score = minimax(board, depth + 1, True)  # 2. Recurse down tree
                    board[r][c] = EMPTY  # 3. Undo move (backtrack)
                    best_score = min(best_score, score)
        return best_score


def find_best_move(board):
    """Iterates through empty spots on current board to pick the highest-scoring AI move."""
    best_score = -999
    best_move = None

    for r in range(3):
        for c in range(3):
            if board[r][c] == EMPTY:
                board[r][c] = AI
                score = minimax(board, depth=0, is_maximizing=False)
                board[r][c] = EMPTY

                if score > best_score:
                    best_score = score
                    best_move = (r, c)

    return best_move


# --- Simple Interactive Loop ---
if __name__ == "__main__":
    board = [[EMPTY] * 3 for _ in range(3)]

    while True:
        # Print current board
        for row in board:
            print(row)

        if check_winner(board) is not None:
            print("Game Over:", check_winner(board))
            break

        # Human move
        r, c = map(int, input("Enter row col (0-2 0-2): ").split())
        if board[r][c] != EMPTY:
            print("Cell occupied! Try again.")
            continue
        board[r][c] = HUMAN

        # AI move
        if check_winner(board) is None:
            ai_move = find_best_move(board)
            if ai_move:
                board[ai_move[0]][ai_move[1]] = AI